/**
 * listenuplads Core PWA Design System Tokens
 * Master Theme & Primitives as specified in JGF-15 Design System Direction (rev 4).
 *
 * Single source of truth for the Nocturnal Chamber palette. CSS custom
 * properties are generated by getThemeCssVariables() and injected once at boot
 * (see main.ts) — stylesheets consume var(--token-*) and never hardcode hexes.
 */

export const sharedTokens = {
  spacing: {
    1: "4px",
    2: "8px",
    3: "12px",
    4: "16px",
    5: "20px",
    6: "24px",
    8: "32px",
    10: "40px",
    12: "48px",
    16: "64px",
  },
  radius: {
    none: "0px",
    sm: "6px",
    md: "10px",
    lg: "16px",
    xl: "24px",
    full: "9999px",
  },
  motion: {
    durationFast: "150ms",
    durationNormal: "250ms",
    durationSlow: "400ms",
    easeDefault: "cubic-bezier(0.16, 1, 0.3, 1)", // Ease out expo
    easeSpring: "cubic-bezier(0.34, 1.56, 0.64, 1)",
  },
  typography: {
    textXs: "12px",
    textChip: "clamp(13px, 3.6vw, 14px)", // dense shelf chips: FR-safe floor of 13px
    textSm: "14px",
    textMd: "16px",
    textLg: "20px",
    textXl: "28px",
    leadingTight: "1.2",
    leadingBody: "1.45",
  },
  accessibility: {
    focusRing: "2px solid var(--token-focus, #D8B4FE)",
    focusOffset: "2px",
    touchTargetMin: "44px",
  },
} as const;

export const listenupladsTheme = {
  colors: {
    bgApp: "#0A070F", // Obsidian base
    bgCard: "#15101F", // Velvet shadow
    bgElevated: "#201830", // Muted amethyst
    borderSubtle: "#2D2342", // Deep plum border
    borderAccent: "rgba(216, 180, 254, 0.3)", // Electric lavender translucent
    borderWarmth: "rgba(251, 191, 36, 0.3)", // Amber gold translucent (crypto rail)
    textPrimary: "#F5EEF8", // Soft pale lilac
    textSecondary: "#B3A5C4", // Muted mauve
    textMuted: "#7B6F8E", // Subtle lavender
    textOnAccent: "#1B0F22", // Dark plum typography on luminous accent fills
    accentPrimary: "#D8B4FE", // Electric Lavender
    accentSecondary: "#FF6EA9", // Hot Magenta
    accentWarmth: "#FBBF24", // Amber Gold / Aftercare
    success: "#7EE2B8", // Mint green
    error: "#FF9DB8", // Soft rose error
  },
  typography: {
    fontSans: "Outfit, Inter, system-ui, -apple-system, sans-serif",
    fontDisplay: '"Playfair Display", Georgia, serif',
    fontMono: 'ui-monospace, "JetBrains Mono", monospace',
  },
} as const;

/**
 * Returns CSS custom properties string for listenuplads theme.
 * Injected into <head> at boot; every surface reads var(--token-*).
 */
export function getThemeCssVariables(): string {
  return `
:root {
  --token-bg-app: ${listenupladsTheme.colors.bgApp};
  --token-bg-card: ${listenupladsTheme.colors.bgCard};
  --token-bg-elevated: ${listenupladsTheme.colors.bgElevated};
  --token-border-subtle: ${listenupladsTheme.colors.borderSubtle};
  --token-border-accent: ${listenupladsTheme.colors.borderAccent};
  --token-border-warmth: ${listenupladsTheme.colors.borderWarmth};
  --token-text-primary: ${listenupladsTheme.colors.textPrimary};
  --token-text-secondary: ${listenupladsTheme.colors.textSecondary};
  --token-text-muted: ${listenupladsTheme.colors.textMuted};
  --token-text-on-accent: ${listenupladsTheme.colors.textOnAccent};
  --token-accent-primary: ${listenupladsTheme.colors.accentPrimary};
  --token-accent-secondary: ${listenupladsTheme.colors.accentSecondary};
  --token-accent-warmth: ${listenupladsTheme.colors.accentWarmth};
  --token-success: ${listenupladsTheme.colors.success};
  --token-error: ${listenupladsTheme.colors.error};
  --token-focus: ${listenupladsTheme.colors.accentPrimary};

  /* Dynamic player accent: lavender in play mode, amber in Aftercare mode.
     Registered as a real <color> in player.css via @property so the
     aftercare toggle can crossfade it (250–400ms, shared ease). */
  --token-accent-dynamic: ${listenupladsTheme.colors.accentPrimary};

  --token-font-sans: ${listenupladsTheme.typography.fontSans};
  --token-font-display: ${listenupladsTheme.typography.fontDisplay};
  --token-font-mono: ${listenupladsTheme.typography.fontMono};

  --token-text-xs: ${sharedTokens.typography.textXs};
  --token-text-chip: ${sharedTokens.typography.textChip};
  --token-text-sm: ${sharedTokens.typography.textSm};
  --token-text-md: ${sharedTokens.typography.textMd};
  --token-text-lg: ${sharedTokens.typography.textLg};
  --token-text-xl: ${sharedTokens.typography.textXl};
  --token-leading-tight: ${sharedTokens.typography.leadingTight};
  --token-leading-body: ${sharedTokens.typography.leadingBody};

  --token-space-1: ${sharedTokens.spacing[1]};
  --token-space-2: ${sharedTokens.spacing[2]};
  --token-space-3: ${sharedTokens.spacing[3]};
  --token-space-4: ${sharedTokens.spacing[4]};
  --token-space-5: ${sharedTokens.spacing[5]};
  --token-space-6: ${sharedTokens.spacing[6]};
  --token-space-8: ${sharedTokens.spacing[8]};
  --token-space-10: ${sharedTokens.spacing[10]};
  --token-space-12: ${sharedTokens.spacing[12]};
  --token-space-16: ${sharedTokens.spacing[16]};

  --token-radius-sm: ${sharedTokens.radius.sm};
  --token-radius-md: ${sharedTokens.radius.md};
  --token-radius-lg: ${sharedTokens.radius.lg};
  --token-radius-xl: ${sharedTokens.radius.xl};
  --token-radius-full: ${sharedTokens.radius.full};

  --token-dur-fast: ${sharedTokens.motion.durationFast};
  --token-dur-normal: ${sharedTokens.motion.durationNormal};
  --token-dur-slow: ${sharedTokens.motion.durationSlow};
  --token-ease-default: ${sharedTokens.motion.easeDefault};
  --token-ease-spring: ${sharedTokens.motion.easeSpring};

  --token-touch-min: ${sharedTokens.accessibility.touchTargetMin};
}
`.trim();
}
